import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"Week 6 — Tests as Oracles","description":"","frontmatter":{"source":"weeks/06-tests-as-oracles/README.md"},"headers":[],"relativePath":"weeks/06-tests-as-oracles/index.md","filePath":"weeks/06-tests-as-oracles/index.md"}'),s={name:"weeks/06-tests-as-oracles/index.md"};function n(i,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="week-6--tests-as-oracles" tabindex="-1">Week 6 — Tests as Oracles <a class="header-anchor" href="#week-6--tests-as-oracles" aria-label="Permalink to &quot;Week 6 — Tests as Oracles&quot;">​</a></h1><blockquote><p>A test is only as good as the thing that decides what &quot;correct&quot; is: expected values copied from the code agree with its bugs, while properties taken from the specification, run on inputs that reach the hard cases, find them.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Read the reading and post your reading response on Canvas · submit the week 5 assignment (the Seminar opens with its quiz) · if a graduate paper is presented, post one question about it (<a href="./../../graduate/paper-presentations.html#questions-from-the-class">how</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz on recurring bookings (7 min, 🔴 AI off) · talk (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-06.html" target="_blank" rel="noreferrer">slides</a>) · reading discussion, or the graduate presentation of this week&#39;s paper · demo: an agent&#39;s tests agree with a bug; a property from the policy text doesn&#39;t · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--properties-that-find-bugs-75-min">Property-based testing</a> of <code>roomly</code> with fast-check: generators that reach the interesting values, shrinking, reading counterexamples, and judging an agent&#39;s proposed properties. <strong>Checkoff:</strong> one property that fails on the shipped code, with a shrunk counterexample</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--a-property-suite-bug-reports-and-fixes">assignment</a>: a property suite covering the Booking rules, a bug report for every real bug found, and fixes with regression tests in a branch</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: property code, generators and fixes (Safe Loop); an agent proposing properties · 🟡 AI limited: bug reports (yours; an agent may help shrink a reproduction, logged) · 🔴 AI off: the quiz, the reading response, and your verdicts on the agent&#39;s properties</td></tr><tr><td><strong>Reading</strong></td><td>Maaz, DeVoe, Hatfield-Dodds &amp; Carlini, <a href="https://arxiv.org/abs/2510.09907" target="_blank" rel="noreferrer">&quot;Agentic Property-Based Testing: Finding Bugs Across the Python Ecosystem&quot;</a> (NeurIPS 2025)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, before the Seminar (prompt <a href="#reading">below</a>)</td></tr><tr><td><strong>Team project</strong></td><td>M0 feedback arrives within a week (Go, Shrink or Rethink). Start your M1 issue, and find one invariant in your feature area worth a property test: fast-check or Hypothesis, depending on the class codebase (<a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td>Maaz et al. is this week&#39;s seminar paper. <strong>Study protocol</strong> due before the week 7 Seminar (<a href="./../../templates/STUDY_PROTOCOL.html">template</a>; <a href="./../../graduate/empirical-study.html">empirical study</a>)</td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h): reading and response 45 min, assignment about 3.5 h, team project about 1.75 h</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Explain the <a href="./../../resources/glossary.html#oracle">oracle</a> problem, and why tests whose expected values come from the code agree with its bugs.</li><li>Write <a href="./../../resources/glossary.html#property-based-testing">property-based tests</a> with fast-check in five patterns: model, differential, round trip, metamorphic and invariant.</li><li>Design generators that reach the interesting values (boundaries, clock changes in the building&#39;s time zone, roles), and show with statistics that they do.</li><li>Read a shrunk counterexample, replay it, and decide from the specification whether the code or the property is wrong.</li><li>Judge properties an agent proposes against a written specification.</li><li>Write bug reports a maintainer can act on, and fix bugs test first.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Minutes</th><th>What happens</th></tr></thead><tbody><tr><td>Due-date quiz</td><td>7</td><td>On your week 5 assignment (<a href="./../../assessment/quizzes.html">quizzes</a>), 🔴 AI off</td></tr><tr><td>Concept talk</td><td>25</td><td>Oracles; tests that agree with bugs; TDD with agents; properties, generators and shrinking (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-06.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>Reading discussion</td><td>20</td><td>Maaz et al., or its graduate presentation (then talk 18 · presentation 20 · discussion 12)</td></tr><tr><td>Live demo</td><td>10</td><td>An agent writes tests for a small function from its code, and they pass on a bug; a property written from the policy text fails</td></tr><tr><td>Lab preview</td><td>5</td><td>Start from the <code>shipped</code> tag; the checkoff</td></tr></tbody></table><p>The evidence on LLM-written tests: their oracles tend to capture what the code does, not what it should do (<a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">Konstantinou, Degiovanni &amp; Papadakis</a>, preprint); across 14,320 such tests, null inputs were tested 34.8% of the time and negative values 23.8%, against over 93% for booleans (<a href="https://arxiv.org/abs/2610.32548" target="_blank" rel="noreferrer">Shi et al.</a>, preprint); on 3,909 real functions they reached 45.1% statement coverage and a 40.2% mutation score (<a href="https://arxiv.org/abs/2508.00408" target="_blank" rel="noreferrer">Huang et al.</a>, preprint); at Meta only 25% raised coverage at all (<a href="https://arxiv.org/abs/2402.09171" target="_blank" rel="noreferrer">Alshahwan et al.</a>). Yet an agent writing <em>property-based</em> tests found real bugs: 56% of its reports were valid (<a href="https://arxiv.org/abs/2510.09907" target="_blank" rel="noreferrer">Maaz et al.</a>).</p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The <a href="./lab.html#lab--properties-that-find-bugs-75-min">lab</a> returns to the <a href="https://github.com/Boyu-Zhang-UOI/eswa-roomly" target="_blank" rel="noreferrer"><code>roomly</code> kit</a>, starting from the code as shipped (the <code>shipped</code> tag from <a href="./../05-spec-driven-development/">week 5</a>). Its README says that when the code and the Booking rules disagree, the code is wrong: the rules are your oracle. The shipped tests pass, and they miss several real bugs. You build generators that reach the values where rules bite, watch a uniform generator miss what a biased one finds, judge an agent&#39;s proposed properties, and hunt until a property fails. The <a href="./lab.html#assignment--a-property-suite-bug-reports-and-fixes">assignment</a> covers every rule, reports every real bug, and fixes them test first.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Maaz, DeVoe, Hatfield-Dodds &amp; Carlini, <a href="https://arxiv.org/abs/2510.09907" target="_blank" rel="noreferrer">&quot;Agentic Property-Based Testing: Finding Bugs Across the Python Ecosystem&quot;</a></strong> (NeurIPS 2025; <a href="https://github.com/mmaaz-git/agentic-pbt" target="_blank" rel="noreferrer">code</a>). An agent driven by one Markdown prompt wrote and triaged Hypothesis property tests for 100 Python packages; 56% of its bug reports were valid, 86% of the top-ranked 21, and patches were merged in NumPy and elsewhere. Read the abstract, the method and the results; skim the rest.</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off, on Canvas): State the main claim with its numbers. Where did the agent&#39;s oracle come from, the code or something else, and how did the authors decide that a report was a valid bug? What do the invalid reports suggest you should check before trusting a property an agent proposes for <code>roomly</code>? End with one question for the Seminar.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>The oracle decides.</strong> A test checks agreement with an oracle. If the expected values were read off the code, by you or an LLM, the test agrees with whatever the code does, bugs included. <code>roomly</code>&#39;s oracle is its Booking rules.</li><li><strong>Check first, still.</strong> Write the test or property from the rule, in a separate session from the code; never let an agent edit a test to make it pass (<a href="./../../resources/agent-patterns.html#check-first">check first</a>).</li><li><strong>A property is a claim about all inputs.</strong> fast-check generates inputs (100 by default), and when one fails it <em>shrinks</em> it to a small counterexample you can read.</li><li><strong>Generators decide what you find.</strong> A uniform date over three years lands on one of the six clock-change days about once in 180 draws. Bias generators toward boundaries, clock changes and roles, and measure the bias with <code>fc.statistics</code>.</li><li><strong>Read the counterexample against the spec.</strong> Sometimes the code is wrong; sometimes the property claims more than the spec does. Decide which from the written rule, not from intuition.</li><li><strong>An agent proposes; you judge.</strong> Keep a proposed property only if it follows from a rule you can cite.</li><li><strong>A bug report is a reproduction.</strong> The rule violated, a minimal case anyone can run, expected versus actual.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>An agent reads <code>checkIn()</code> and writes a test expecting <code>409</code> for a check-in 16 minutes after the start. What makes that a good test or a bad one?</li><li>Why do small integer ranges find boundary bugs that <code>fc.integer()</code> misses?</li><li>A property passes 100 runs with uniform dates. What can you conclude about the days the clocks change?</li><li>A property fails with the counterexample <code>[&quot;2026-03-08&quot;,&quot;02:00&quot;]</code>. What do you check before you report a bug?</li><li>Give a metamorphic property for a booking system, one that needs no model of the right answer.</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong><code>npm install</code> fails:</strong> check <code>node --version</code> and retry. With no registry at all, write the property as a plain loop over a hand-made list of interesting values (boundaries, the six clock-change days, every role). You lose random exploration and shrinking: say so.</li><li><strong>The agent is down for Part 3:</strong> staff post a saved list of agent-proposed properties; judge those.</li><li><strong>Codespaces down:</strong> <code>roomly</code> runs locally with Node 20.12 or later.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>The <a href="https://github.com/mmaaz-git/agentic-pbt" target="_blank" rel="noreferrer">agentic-pbt code</a>: the prompt is a skill you can read.</li><li>Konstantinou, Degiovanni &amp; Papadakis, <a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">&quot;Can we find bugs using LLM-generated oracles?&quot;</a>, and Shi et al., <a href="https://arxiv.org/abs/2610.32548" target="_blank" rel="noreferrer">&quot;Beyond Coverage and Mutation&quot;</a>.</li><li>Previous week: <a href="./../05-spec-driven-development/">Spec-Driven Development</a>. Next week: <a href="./../07-test-adequacy/">Measuring Test Adequacy</a>, which asks how good your new suite is.</li></ul>',23)])])}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
